/**
 * Worker API end-to-end test.
 *
 * Unlike the unit tests, this calls the **real Worker entry point**
 * (`worker/src/app.ts` fetch handler) with real Request objects, over the index
 * generated by the real indexer, against a real R2 binding surface. It exercises
 * routing, Zod validation, the Access middleware, the R2 read path, CSV export
 * generation and error handling exactly as a request does in production — the
 * only substitution is the R2 binding itself (an in-memory object store) and the
 * Access identity (the explicit local-development bypass, which cannot engage in
 * production: `tests/security-access.test.ts` asserts that separately).
 *
 * It is not workerd. Bun runs the same code path; anything specific to the
 * Cloudflare runtime (CPU accounting, subrequest limits, isolate cold starts)
 * still needs a real deployment measurement, which is reported as pending.
 */

import { describe, expect, test } from "bun:test";

import { app } from "../worker/src/app";
import type { Env } from "../worker/src/env";
import { FakeR2Bucket } from "./helpers/fake-r2";
import { buildFixtureDataset } from "./helpers/fixture-dataset";
import { activeManifestKey } from "../src/shared/search/index-format";

const fixture = await buildFixtureDataset();
const bucket = new FakeR2Bucket();
bucket.loadObjects(
  fixture.outputDir,
  fixture.result.objects.map((object) => object.key),
);
bucket.putBytes(
  activeManifestKey(),
  Buffer.from(JSON.stringify({ version: fixture.version, previousVersion: null, activatedAt: new Date().toISOString() }), "utf8"),
);
// The original CSVs, as they would exist under raw/ in the real bucket.
bucket.putBytes("raw/source-one.csv", Buffer.from("Company Name,Website\nAcme, Inc.,https://acme.example\n", "utf8"), {
  contentType: "text/csv",
});
bucket.putBytes("raw/source-two.csv", Buffer.from("organization,domain\nAcme Inc,acme.example\n", "utf8"), {
  contentType: "text/csv",
});

const env = {
  COMPANY_DATA: bucket,
  ENVIRONMENT: "development",
  DEV_ALLOW_UNAUTHENTICATED: "true",
  MAX_SEARCHES_PER_MINUTE: "100000",
  APP_VERSION: "test",
} as unknown as Env;

const ctx = { waitUntil: () => {}, passThroughOnException: () => {} } as unknown as ExecutionContext;

/**
 * Whatever `JSON.parse` returns: these tests assert on the JSON of *arbitrary*
 * endpoints, including error envelopes, so the shape is intentionally dynamic.
 */
type ParsedJson = ReturnType<typeof JSON.parse>;

async function api(path: string, init?: RequestInit): Promise<{ status: number; body: ParsedJson }> {
  const response = await app.fetch(new Request(`https://companyintel.example${path}`, init), env, ctx);
  const text = await response.text();
  let body: ParsedJson = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text;
  }
  return { status: response.status, body };
}

const json = (method: string, payload?: unknown): RequestInit => ({
  method,
  headers: { "content-type": "application/json" },
  body: payload === undefined ? undefined : JSON.stringify(payload),
});

/* -------------------------------------------------------------------------- */

describe("Worker API routes (real fetch handler)", () => {
  test("GET /api/health reports the environment and identity", async () => {
    const { status, body } = await api("/api/health");
    expect(status).toBe(200);
    expect(body.ok).toBe(true);
    expect(body.service).toBe("companyintel-worker");
    expect(body.environment).toBe("development");
    expect(typeof body.identity).toBe("string");
  });

  test("GET /api/dataset/status reports the published fixture version", async () => {
    const { status, body } = await api("/api/dataset/status");
    expect(status).toBe(200);
    expect(body.indexed).toBe(true);
    expect(body.activeVersion).toBe(fixture.version);
    expect(body.dataOrigin).toBe("r2");
    expect(body.sources.map((source: { id: string }) => source.id)).toEqual(["csv1", "csv2"]);
    expect(body.versions.length).toBeGreaterThan(0);
  });

  test("GET /api/dataset/sources lists the real raw/ objects with sizes", async () => {
    bucket.resetCounters();
    const { status, body } = await api("/api/dataset/sources");
    expect(status).toBe(200);
    expect(body.bucket).toBe("company-intel-data");
    expect(body.error).toBeUndefined();
    expect(body.objects.map((object: { key: string }) => object.key)).toEqual([
      "raw/source-one.csv",
      "raw/source-two.csv",
    ]);
    for (const object of body.objects) {
      expect(typeof object.sizeBytes).toBe("number");
      expect(object.sizeBytes).toBeGreaterThan(0);
    }
    // One LIST (a Class A operation) per request, never a bucket walk.
    expect(bucket.counters.lists).toBe(1);
  });

  test("GET /api/companies/search finds exact, fuzzy and prefix matches", async () => {
    const exact = await api("/api/companies/search?q=Microsoft%20Corporation");
    expect(exact.status).toBe(200);
    expect(exact.body.hits[0].name).toBe("Microsoft Corporation");
    expect(exact.body.datasetVersion).toBe(fixture.version);
    expect(typeof exact.body.tookMs).toBe("number");

    const fuzzy = await api("/api/companies/search?q=Microsft");
    expect(fuzzy.body.hits[0].name).toBe("Microsoft Corporation");

    const prefix = await api("/api/companies/search?q=micro");
    expect(prefix.body.hits.some((hit: { name: string }) => hit.name === "Microsoft Corporation")).toBe(true);

    const none = await api("/api/companies/search?q=zzzzzzqqqqq");
    expect(none.status).toBe(200);
    expect(none.body.hits).toEqual([]);
    expect(none.body.page.total).toBe(0);
  });

  test("invalid search parameters are rejected with a readable 400", async () => {
    const { status, body } = await api("/api/companies/search?page=0&pageSize=9999");
    expect(status).toBe(400);
    expect(body.error.code).toBe("invalid_request");
    expect(body.error.requestId).toBeTruthy();
  });

  test("company detail returns a profile with facets", async () => {
    const search = await api("/api/companies/search?q=Microsoft");
    const id = search.body.hits[0].id as string;
    const { status, body } = await api(`/api/companies/${encodeURIComponent(id)}`);
    expect(status).toBe(200);
    expect(body.company.name).toBe("Microsoft Corporation");
    expect(body.company.contactCount).toBe(4);
    expect(body.datasetVersion).toBe(fixture.version);
    expect(Array.isArray(body.facets.designations)).toBe(true);
  });

  test("company contacts paginate and filter server-side", async () => {
    const search = await api("/api/companies/search?q=Microsoft");
    const id = search.body.hits[0].id as string;

    const page = await api(`/api/companies/${encodeURIComponent(id)}/contacts?page=1&pageSize=2`);
    expect(page.status).toBe(200);
    expect(page.body.contacts).toHaveLength(2);
    expect(page.body.page.hasMore).toBe(true);

    const second = await api(`/api/companies/${encodeURIComponent(id)}/contacts?page=2&pageSize=2`);
    const firstIds = page.body.contacts.map((contact: { id: string }) => contact.id);
    const secondIds = second.body.contacts.map((contact: { id: string }) => contact.id);
    expect(firstIds.filter((id: string) => secondIds.includes(id))).toEqual([]);

    const filtered = await api(
      `/api/companies/${encodeURIComponent(id)}/contacts?pageSize=25&department=Finance`,
    );
    expect(filtered.status).toBe(200);
    expect(filtered.body.contacts.map((contact: { fullName: string }) => contact.fullName)).toEqual(["Amy Hood"]);
  });

  test("a single contact resolves by id", async () => {
    const search = await api("/api/companies/search?q=Infosys");
    const id = search.body.hits[0].id as string;
    const contacts = await api(`/api/companies/${encodeURIComponent(id)}/contacts?pageSize=25`);
    const contactId = contacts.body.contacts[0].id as string;
    const { status, body } = await api(`/api/contacts/${encodeURIComponent(contactId)}`);
    expect(status).toBe(200);
    expect(body.contact.id).toBe(contactId);
    expect(body.company.name).toBe("Infosys Limited");
  });

  test("saved leads round-trip through R2 (save → list → patch → delete)", async () => {
    const search = await api("/api/companies/search?q=Globex");
    const targetId = search.body.hits[0].id as string;

    const saved = await api(
      "/api/leads",
      json("POST", { kind: "company", targetId, status: "new", tags: ["priority"], datasetVersion: fixture.version }),
    );
    expect(saved.status).toBe(201);
    expect(saved.body.name).toBe("Globex Corporation");

    const listed = await api("/api/leads");
    expect(listed.body.total).toBe(1);

    const patched = await api(
      `/api/leads/${encodeURIComponent(saved.body.id)}`,
      json("PATCH", { status: "contacted", addNote: "Called the switchboard" }),
    );
    expect(patched.status).toBe(200);
    expect(patched.body.status).toBe("contacted");
    expect(patched.body.notes.at(-1).text).toBe("Called the switchboard");

    const deleted = await api(`/api/leads/${encodeURIComponent(saved.body.id)}`, { method: "DELETE" });
    expect(deleted.status).toBe(200);
    expect((await api("/api/leads")).body.total).toBe(0);

    // Deleting twice is a 404, not a silent success.
    const again = await api(`/api/leads/${encodeURIComponent(saved.body.id)}`, { method: "DELETE" });
    expect(again.status).toBe(404);
  });

  test("saving a lead for an id outside the dataset is rejected", async () => {
    const { status, body } = await api(
      "/api/leads",
      json("POST", { kind: "company", targetId: "not-in-dataset", status: "new", tags: [], datasetVersion: fixture.version }),
    );
    expect(status).toBe(404);
    expect(body.error.code).toBe("not_found");
  });

  test("a lost lead directory self-heals through the API, and can be repaired explicitly", async () => {
    const search = await api("/api/companies/search?q=Globex");
    const targetId = search.body.hits[0].id as string;
    await api("/api/leads", json("POST", { kind: "company", targetId, status: "new", tags: [], datasetVersion: fixture.version }));

    // A crash between the shard write and the directory write.
    bucket.objects.delete("app-data/leads/index.json");

    const listed = await api("/api/leads");
    expect(listed.status).toBe(200);
    expect(listed.body.total).toBe(1);

    const repaired = await api("/api/leads/repair", { method: "POST" });
    expect(repaired.status).toBe(200);
    expect(repaired.body.repaired).toBe(true);
    expect(repaired.body.total).toBe(1);
    expect(repaired.body.partitions).toBe(1);

    // Clean up so later tests start from an empty lead list.
    for (const lead of (await api("/api/leads")).body.leads) {
      await api(`/api/leads/${encodeURIComponent(lead.id)}`, { method: "DELETE" });
    }
  });

  test("saved searches round-trip and can be re-run", async () => {
    const created = await api("/api/saved-searches", json("POST", { name: "MSFT", query: "microsoft" }));
    expect(created.status).toBe(201);
    expect(created.body.query).toBe("microsoft");

    const list = await api("/api/saved-searches");
    expect(list.body.map((search: { name: string }) => search.name)).toEqual(["MSFT"]);

    const run = await api(`/api/saved-searches/${encodeURIComponent(created.body.id)}/run`, { method: "POST" });
    expect(run.status).toBe(200);
    expect(run.body.lastRunAt).toBeTruthy();

    const removed = await api(`/api/saved-searches/${encodeURIComponent(created.body.id)}`, { method: "DELETE" });
    expect(removed.status).toBe(200);
    expect((await api("/api/saved-searches")).body).toEqual([]);
  });

  test("settings round-trip", async () => {
    const initial = await api("/api/settings");
    expect(initial.status).toBe(200);
    const updated = await api("/api/settings", json("PUT", { pageSize: 50, fuzzySearch: false }));
    expect(updated.status).toBe(200);
    expect(updated.body.pageSize).toBe(50);
    expect((await api("/api/settings")).body.fuzzySearch).toBe(false);
  });

  test("activity records and lists", async () => {
    await api("/api/activity", json("POST", { kind: "search", label: "microsft" }));
    const { status, body } = await api("/api/activity");
    expect(status).toBe(200);
    expect(body[0].label).toBe("microsft");
  });

  test("CSV export generates a downloadable, formula-safe file", async () => {
    const search = await api("/api/companies/search?q=Microsoft");
    const companyId = search.body.hits[0].id as string;
    const contacts = await api(`/api/companies/${encodeURIComponent(companyId)}/contacts?pageSize=25`);
    const contactIds = contacts.body.contacts.map((contact: { id: string }) => contact.id);

    const created = await api(
      "/api/exports",
      json("POST", {
        kind: "contacts",
        columns: ["fullName", "title", "email", "companyName"],
        contactIds,
        datasetVersion: fixture.version,
      }),
    );
    expect(created.status).toBe(201);
    expect(created.body.rowCount).toBe(4);

    const download = await app.fetch(
      new Request(`https://companyintel.example/api/exports/${encodeURIComponent(created.body.id)}/download`),
      env,
      ctx,
    );
    expect(download.status).toBe(200);
    expect(download.headers.get("content-type")).toContain("text/csv");
    expect(download.headers.get("cache-control")).toContain("no-store");
    const csv = await download.text();
    // Human-readable headers, in the column order the request asked for.
    expect(csv.split("\r\n")[0]).toBe("Contact Name,Job Title,Email,Company");
    expect(csv).toContain("satya.nadella@microsoft.com");
    expect(csv).toContain("Microsoft Corporation");
  });

  test("unknown API routes return a structured 404, not an HTML crash", async () => {
    const { status, body } = await api("/api/does-not-exist");
    expect(status).toBe(404);
    expect(body?.error?.code ?? "not_found").toBeTruthy();
  });

  test("cross-origin API calls are refused", async () => {
    const response = await app.fetch(
      new Request("https://companyintel.example/api/health", { headers: { origin: "https://evil.example" } }),
      env,
      ctx,
    );
    expect(response.status).toBe(403);
  });

  test("security headers are present on API responses", async () => {
    const response = await app.fetch(new Request("https://companyintel.example/api/health"), env, ctx);
    expect(response.headers.get("x-content-type-options")).toBe("nosniff");
    expect(response.headers.get("x-frame-options")).toBe("DENY");
    expect(response.headers.get("referrer-policy")).toBe("no-referrer");
    expect(response.headers.get("x-request-id")).toBeTruthy();
  });

  test("without an Access identity the API refuses to serve (fail closed)", async () => {
    const locked = { ...env, ENVIRONMENT: "production", DEV_ALLOW_UNAUTHENTICATED: undefined } as unknown as Env;
    for (const path of ["/api/health", "/api/companies/search?q=microsoft", "/api/leads"]) {
      const response = await app.fetch(new Request(`https://companyintel.example${path}`), locked, ctx);
      expect(response.status).toBeGreaterThanOrEqual(401);
      expect(response.status).not.toBe(200);
    }
  });
});
